import React, { useState, useEffect } from 'react'
import Navbar from '../components/Navbar'
import Footer from '../components/Footer'

export default function MyOrder() {
  const [orderData, setorderData] = useState({})

  const fetchMyOrder = async () => {
    console.log(localStorage.getItem('userEmail'))
    await fetch("https://gofood-fulstack-mern-app.onrender.com/api/myOrderData", {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        email: localStorage.getItem('userEmail')
      })
    }).then(async (res) => {
      let response = await res.json()
      setorderData(response)
    })
  }

  useEffect(() => {
    fetchMyOrder()
  }, [])

  return (
    <>
      <div><Navbar /></div>
      <div className='container'>
        <div className='row'>
          {orderData && orderData.orderData && orderData.orderData.order_data
            ? orderData.orderData.order_data.slice(0).reverse().map((item, idx) => (
              <React.Fragment key={idx}>
                {item.map((arrayData, i) => (
                  arrayData.Order_date ? (
                    <div className='m-auto mt-5' key={i}>
                      {arrayData.Order_date}
                      <hr />
                    </div>
                  ) : (
                    <div className='col-12 col-md-6 col-lg-3' key={i}>
                      <div className="card mt-3" style={{ width: "16rem", maxHeight: "360px" }}>
                        <img src={arrayData.img} className="card-img-top" alt="..." style={{ height: "120px", objectFit: "fill" }} />
                        <div className="card-body">
                          <h5 className="card-title">{arrayData.name}</h5>
                          <div className='container w-100 p-0' style={{ height: "38px" }}>
                            <span className='m-1'>{arrayData.qty}</span>
                            <span className='m-1'>{arrayData.size}</span>
                            <span className='m-1'>{arrayData.Order_date}</span>
                            <div className=' d-inline ms-2 h-100 w-20 fs-5' >
                              ₹{arrayData.price}/-
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  )
                ))}
              </React.Fragment>
            ))
            : ""}
        </div>
      </div>
      <div><Footer /></div>
    </>
  )
}
